-- Early YC-network backing (STRICT): of each repo's FIRST 100 / 1000 stargazers (by time),
-- how many also star >=2 OTHER YC-OSS repos. "multi" = accounts that starred >=3 tracked repos
-- total; a stargazer of repo R already stars R, so >=3 total => >=2 others. De-identified, no
-- logins emitted. Also outputs the all-time share under the same strict definition.
WITH s AS (
  SELECT actor.login AS a, repo.id AS r, MIN(created_at) AS t
  FROM `githubarchive.month.*`
  WHERE _TABLE_SUFFIX BETWEEN '201501' AND '202606' AND type='WatchEvent' AND repo.id IN (36437041, 235901813, 521655652, 660776503, 461280850, 606164768, 294714234, 2500088, 342728683, 738290765, 628390075, 271816968, 231921809, 543838169, 285012857, 380046663, 283046497, 639096757, 75255555, 326404870, 597502256, 886966165, 450188582, 736272311, 202291859, 614695583, 299482335, 732124850, 914997268, 547597394, 50874442, 143328315, 201403923, 463728195, 879336205, 764723738, 358943289, 1090300896, 642497346, 557075997, 971447302, 621803253, 1066745758, 481955061, 351486934, 476820102, 900550981, 1144115288, 963696290, 573661753, 116817549, 14702444, 359995930, 1002125012, 881458615, 771160970, 6452529, 775009948, 168712350, 1076362809, 658928958, 1144115288, 365373172, 370119131, 1177108326, 783445370, 257787813, 839037098, 676829188, 289073337, 637924634, 501725302, 52630616, 143846881, 524510950, 1044426027, 19257422, 605682921, 342259394, 290495697, 434630945, 677829141, 123606765, 480715758, 619284964, 254328371, 357728969, 145464445, 664872761, 595832198, 13124802, 725205304, 690825026, 401275197, 88013053, 624681066, 656099147, 671269505, 371296634, 621929252, 516192901, 304588125, 360238600, 285092252, 718873539, 371644903, 396569538, 488804911, 181399273, 787076358, 775144062, 349372179, 348217288, 21233191, 464415161, 686364232, 607441698, 327089870, 420489845, 331293626, 3757512, 214587193, 100346588, 846729675, 803014189, 396856161, 237222619, 572570113, 672387589, 1028159967, 362806180, 510034344, 152572186, 704537857, 546358763, 956472076, 572984571, 3470471, 11225014, 315977578, 916009087, 1125445550, 863835427, 654560183, 936400285, 438113412, 633262635, 649170660, 655949187, 601834373, 1147073855, 893031915, 37448451, 763923484, 325724738, 1017038703, 973180254, 925270205)
  GROUP BY a, r ),
multi AS ( SELECT a FROM s GROUP BY a HAVING COUNT(*) >= 3 ),
ranked AS ( SELECT r, a, ROW_NUMBER() OVER (PARTITION BY r ORDER BY t) AS rn FROM s )
SELECT r AS repo_id,
  COUNTIF(rn<=100)  AS first100,  COUNTIF(rn<=100  AND a IN (SELECT a FROM multi)) AS first100_net,
  COUNTIF(rn<=1000) AS first1000, COUNTIF(rn<=1000 AND a IN (SELECT a FROM multi)) AS first1000_net,
  COUNT(*)          AS total,     COUNTIF(a IN (SELECT a FROM multi))              AS total_net
FROM ranked GROUP BY r
